edges = [(u, v) for u in range(6) for v in range(6, 12)]
# Verify triangle-free
adj = {i:set() for i in range(12)}
for u,v in edges:
    adj[u].add(v); adj[v].add(u)
# Check no triangle
for a in range(12):
    for b in adj[a]:
        if b>a:
            if adj[a] & adj[b]:
                print("TRIANGLE", a,b)
# Check maximal: for each non-edge, adding it must create a triangle
for a in range(12):
    for b in range(a+1,12):
        if b not in adj[a]:
            if not (adj[a] & adj[b]):
                print("NOT MAXIMAL", a,b)
print("edges:", len(edges))
print(edges)
